        auto& parent = tmt::engine.ecs.add_component<tmt::Transform>(parent_entity);
        auto& child = tmt::engine.ecs.add_component<tmt::Transform>(child_entity);

        // Initially no parent
        assert(!child.has_parent());

        // Set parent
        child.set_parent(parent_entity);
        assert(child.has_parent());
        assert(child.get_parent() == parent_entity);

        // Check parent's children list
        const auto& children = parent.get_children();
        assert(children.size() == 1);
        assert(children.count(child_entity) == 1);

        // Clear parent
        child.clear_parent();
        assert(!child.has_parent());
        assert(parent.get_children().empty());

        tmt::engine.ecs.clear();
        std::cout << "Passed\n\n";
