        auto& grandparent = tmt::engine.ecs.add_component<tmt::Transform>(grandparent_entity);
        auto& parent = tmt::engine.ecs.add_component<tmt::Transform>(parent_entity);
        auto& child = tmt::engine.ecs.add_component<tmt::Transform>(child_entity);

        // Set up hierarchy: grandparent -> parent -> child
        parent.set_parent(grandparent_entity);
        child.set_parent(parent_entity);

        // Set positions
        grandparent.set_local_position(glm::vec3(10.0f, 0.0f, 0.0f));
        parent.set_local_position(glm::vec3(5.0f, 0.0f, 0.0f));
        child.set_local_position(glm::vec3(2.0f, 0.0f, 0.0f));

        // Check world positions
        assert(vec3_approx_equal(grandparent.get_world_position(), glm::vec3(10.0f, 0.0f, 0.0f)));
        assert(vec3_approx_equal(parent.get_world_position(), glm::vec3(15.0f, 0.0f, 0.0f)));
        assert(vec3_approx_equal(child.get_world_position(), glm::vec3(17.0f, 0.0f, 0.0f)));

        // Change grandparent position, should affect all
        grandparent.set_local_position(glm::vec3(0.0f, 0.0f, 0.0f));
        assert(vec3_approx_equal(parent.get_world_position(), glm::vec3(5.0f, 0.0f, 0.0f)));
        assert(vec3_approx_equal(child.get_world_position(), glm::vec3(7.0f, 0.0f, 0.0f)));

