        assert(parent.get_children().size() == 2);
        assert(parent.get_children().count(child1_entity) == 1);
        assert(parent.get_children().count(child2_entity) == 1);

        // Remove one child
        parent.remove_child(child1_entity);
        assert(parent.get_children().size() == 1);
        assert(parent.get_children().count(child1_entity) == 0);
        assert(parent.get_children().count(child2_entity) == 1);

        // Remove non-existent child (should not crash)
        parent.remove_child(child1_entity);
        assert(parent.get_children().size() == 1);

        // Remove last child
        parent.remove_child(child2_entity);
        assert(parent.get_children().empty());

