        parent.set_local_rotation(glm::angleAxis(glm::radians(90.0f), glm::vec3(0.0f, 1.0f, 0.0f)));

        // Child at local position (10, 0, 0)
        child.set_local_position(glm::vec3(10.0f, 0.0f, 0.0f));

