        transform.set_local_position(glm::vec3(10.0f, 20.0f, 30.0f));
        transform.set_local_rotation(glm::angleAxis(glm::radians(45.0f), glm::normalize(glm::vec3(1.0f, 1.0f, 1.0f))));
        transform.set_local_scale(glm::vec3(2.0f, 3.0f, 4.0f));

        // Multiple operations
        transform.translate(glm::vec3(5.0f, 5.0f, 5.0f));
        transform.rotate_local(glm::vec3(0.0f, 1.0f, 0.0f), glm::radians(30.0f));
        transform.scale(glm::vec3(1.5f, 1.5f, 1.5f));

        // Verify everything is still valid
