        glm::quat rot = transform.get_local_rotation();
        glm::vec3 scale = transform.get_local_scale();
        glm::mat4 matrix = transform.get_world_matrix();

        assert(!std::isnan(pos.x) && !std::isnan(pos.y) && !std::isnan(pos.z));
        assert(!std::isnan(rot.w) && !std::isnan(rot.x) && !std::isnan(rot.y) && !std::isnan(rot.z));
        assert(!std::isnan(scale.x) && !std::isnan(scale.y) && !std::isnan(scale.z));

